const FilterComponent = () => {
  const [filters, setFilters] = useState({
    status: "All",
    ballType: "All",
    category: "All",
  });

  const handleFilterChange = (filterName, value) => {
    setFilters((prevFilters) => ({
      ...prevFilters,
      [filterName]: value,
    }));
  };

  const filteredData = data.filter((item) => {
    return (
      (filters.status === "All" || item.status === filters.status) &&
      (filters.ballType === "All" || item.ballType === filters.ballType) &&
      (filters.category === "All" || item.category === filters.category)
    );
  });

  return (
    <div className="flex flex-col bg-[#F3F4F4] gap-6 p-4 md:flex-row md:p-8">
      
      <div className="w-full md:w-1/3  p-4 ml-[1%]">
        <h4 className="sm:text-[20px] text-[15px] font-semibold mb-4">Filter Options</h4>

       
        <div className="mb-4">
          <h5 className="sm:text-[18px] text-[14px] font-medium mb-2">Status</h5>
          <div className="space-y-2">
            {["All", "Ongoing", "Upcoming"].map((status) => (
              <label key={status} className="flex items-center space-x-2">
                <input
                  type="radio"
                  name="status"
                  value={status}
                  checked={filters.status === status}
                  onChange={() => handleFilterChange("status", status)}
                  className="w-4 h-4"
                />
                <span className="sm:text-[16px] text-[13px]">{status}</span>
              </label>
            ))}
          </div>
        </div>

      
        <div className="mb-4">
          <h5 className="sm:text-[18px] text-[14px] font-medium mb-2">Ball Type</h5>
          <div className="space-y-2">
            {["Tennis", "Leather"].map((type) => (
              <label key={type} className="flex items-center space-x-2">
                <input
                  type="radio"
                  name="ballType"
                  value={type}
                  checked={filters.ballType === type}
                  onChange={() => handleFilterChange("ballType", type)}
                  className="w-4 h-4"
                />
                <span className="sm:text-[16px] text-[13px]">{type}</span>
              </label>
            ))}
          </div>
        </div>

       
        <div className="mb-4">
          <h5 className="sm:text-[18px] text-[14px] font-medium mb-2">Category</h5>
          <div className="space-y-2">
            {["Corporate", "Open"].map((category) => (
              <label key={category} className="flex items-center space-x-2">
                <input
                  type="radio"
                  name="category"
                  value={category} 
                  checked={filters.category === category}
                  onChange={() => handleFilterChange("category", category)}
                  className="w-4 h-4"
                />
                <span className="sm:text-[16px] text-[13px]">{category}</span>
              </label>
            ))}
          </div>
        </div>
      </div>

     
      <div className="w-full md:w-2/3 ">
        <h4 className="sm:text-[18px] text-[14px] font-semibold mb-4"> <span className=" font-bold">Leather Cricket Tournaments </span> (location)</h4>
        <ul className="grid gap-4 sm:grid-cols-1 lg:grid-cols-2">
  {filteredData.map((item) => (
    <li
      key={item.id}
      className=" bg-white p-4 rounded-lg shadow hover:shadow-lg flex flex-row items-center"
    >
      <div className="w-20 h-20 mb-3">
        {item.logo ? (
          <img
            src={item.logo}
            alt={`${item.name} logo`}
            className="w-full h-full object-cover rounded-xl border  transition-all duration-300 hover:scale-110"
          />
        ) : (
          <div className="w-full h-full bg-gray-200 rounded-5 flex items-center justify-center text-sm text-gray-500">
            No Logo
          </div>
        )}
      </div>
    <div className="flex flex-col justify-center items-center gap-4 p-3">
    <h5 className="text-md font-semibold text-center">{item.name}</h5> 
      <p className="text-sm text-gray-500 text-center">{item.date}</p> 
      <p className="text-sm text-gray-500 text-center"> {item.location}</p>
    </div>
     
    </li>
  ))}
</ul>


      </div>
      
    </div>
    
  );
};

export default FilterComponent;
